// MetricBuilderOption applies changes to default metrics builder.
type MetricBuilderOption interface {
	apply(*MetricsBuilder)
}

type metricBuilderOptionFunc func(mb *MetricsBuilder)

func (mbof metricBuilderOptionFunc) apply(mb *MetricsBuilder) {
	mbof(mb)
}

// WithStartTime sets startTime on the metrics builder.
func WithStartTime(startTime pcommon.Timestamp) MetricBuilderOption {
	return metricBuilderOptionFunc(func(mb *MetricsBuilder) {
		mb.startTime = startTime
	})
}
func NewMetricsBuilder(mbc MetricsBuilderConfig, settings receiver.Settings, options ...MetricBuilderOption) *MetricsBuilder {
	mb := &MetricsBuilder{
		config:                                 mbc,
		startTime:                              pcommon.NewTimestampFromTime(time.Now()),
		metricsBuffer:                          pmetric.NewMetrics(),
		buildInfo:                              settings.BuildInfo,
		metricCockroachdbClusterLocksCount:     newMetricCockroachdbClusterLocksCount(mbc.Metrics.CockroachdbClusterLocksCount),
		metricCockroachdbClusterQueriesActive:  newMetricCockroachdbClusterQueriesActive(mbc.Metrics.CockroachdbClusterQueriesActive),
		metricCockroachdbClusterSessionsActive: newMetricCockroachdbClusterSessionsActive(mbc.Metrics.CockroachdbClusterSessionsActive),
		metricCockroachdbClusterTransactionsActive:     newMetricCockroachdbClusterTransactionsActive(mbc.Metrics.CockroachdbClusterTransactionsActive),
		metricCockroachdbContentionEventsTotal:         newMetricCockroachdbContentionEventsTotal(mbc.Metrics.CockroachdbContentionEventsTotal),
		metricCockroachdbIndexContentionEvents:         newMetricCockroachdbIndexContentionEvents(mbc.Metrics.CockroachdbIndexContentionEvents),
		metricCockroachdbIndexReadsTotal:               newMetricCockroachdbIndexReadsTotal(mbc.Metrics.CockroachdbIndexReadsTotal),
		metricCockroachdbJobsCount:                     newMetricCockroachdbJobsCount(mbc.Metrics.CockroachdbJobsCount),
		metricCockroachdbNodesLive:                     newMetricCockroachdbNodesLive(mbc.Metrics.CockroachdbNodesLive),
		metricCockroachdbNodesTotal:                    newMetricCockroachdbNodesTotal(mbc.Metrics.CockroachdbNodesTotal),
		metricCockroachdbRangesTotal:                   newMetricCockroachdbRangesTotal(mbc.Metrics.CockroachdbRangesTotal),
		metricCockroachdbRangesUnavailable:             newMetricCockroachdbRangesUnavailable(mbc.Metrics.CockroachdbRangesUnavailable),
		metricCockroachdbRangesUnderReplicated:         newMetricCockroachdbRangesUnderReplicated(mbc.Metrics.CockroachdbRangesUnderReplicated),
		metricCockroachdbSchemaChangesActive:           newMetricCockroachdbSchemaChangesActive(mbc.Metrics.CockroachdbSchemaChangesActive),
		metricCockroachdbSessionMemoryAllocated:        newMetricCockroachdbSessionMemoryAllocated(mbc.Metrics.CockroachdbSessionMemoryAllocated),
		metricCockroachdbStatementBytesReadMean:        newMetricCockroachdbStatementBytesReadMean(mbc.Metrics.CockroachdbStatementBytesReadMean),
		metricCockroachdbStatementErrorCount:           newMetricCockroachdbStatementErrorCount(mbc.Metrics.CockroachdbStatementErrorCount),
		metricCockroachdbStatementExecutionCount:       newMetricCockroachdbStatementExecutionCount(mbc.Metrics.CockroachdbStatementExecutionCount),
		metricCockroachdbStatementLatencyParseMean:     newMetricCockroachdbStatementLatencyParseMean(mbc.Metrics.CockroachdbStatementLatencyParseMean),
		metricCockroachdbStatementLatencyPlanMean:      newMetricCockroachdbStatementLatencyPlanMean(mbc.Metrics.CockroachdbStatementLatencyPlanMean),
		metricCockroachdbStatementLatencyRunMean:       newMetricCockroachdbStatementLatencyRunMean(mbc.Metrics.CockroachdbStatementLatencyRunMean),
		metricCockroachdbStatementLatencyServiceMean:   newMetricCockroachdbStatementLatencyServiceMean(mbc.Metrics.CockroachdbStatementLatencyServiceMean),
		metricCockroachdbStatementRetriesMax:           newMetricCockroachdbStatementRetriesMax(mbc.Metrics.CockroachdbStatementRetriesMax),
		metricCockroachdbStatementRowsReadMean:         newMetricCockroachdbStatementRowsReadMean(mbc.Metrics.CockroachdbStatementRowsReadMean),
		metricCockroachdbStatementRowsWrittenMean:      newMetricCockroachdbStatementRowsWrittenMean(mbc.Metrics.CockroachdbStatementRowsWrittenMean),
		metricCockroachdbTableContentionEvents:         newMetricCockroachdbTableContentionEvents(mbc.Metrics.CockroachdbTableContentionEvents),
		metricCockroachdbTransactionBytesReadMean:      newMetricCockroachdbTransactionBytesReadMean(mbc.Metrics.CockroachdbTransactionBytesReadMean),
		metricCockroachdbTransactionExecutionCount:     newMetricCockroachdbTransactionExecutionCount(mbc.Metrics.CockroachdbTransactionExecutionCount),
		metricCockroachdbTransactionLatencyCommitMean:  newMetricCockroachdbTransactionLatencyCommitMean(mbc.Metrics.CockroachdbTransactionLatencyCommitMean),
		metricCockroachdbTransactionLatencyRetryMean:   newMetricCockroachdbTransactionLatencyRetryMean(mbc.Metrics.CockroachdbTransactionLatencyRetryMean),
		metricCockroachdbTransactionLatencyServiceMean: newMetricCockroachdbTransactionLatencyServiceMean(mbc.Metrics.CockroachdbTransactionLatencyServiceMean),
		metricCockroachdbTransactionRetriesMax:         newMetricCockroachdbTransactionRetriesMax(mbc.Metrics.CockroachdbTransactionRetriesMax),
		metricCockroachdbTransactionRowsReadMean:       newMetricCockroachdbTransactionRowsReadMean(mbc.Metrics.CockroachdbTransactionRowsReadMean),
		metricCockroachdbTransactionRowsWrittenMean:    newMetricCockroachdbTransactionRowsWrittenMean(mbc.Metrics.CockroachdbTransactionRowsWrittenMean),
		resourceAttributeIncludeFilter:                 make(map[string]filter.Filter),
		resourceAttributeExcludeFilter:                 make(map[string]filter.Filter),
	}
	if mbc.ResourceAttributes.DbSystemName.MetricsInclude != nil {
		mb.resourceAttributeIncludeFilter["db.system.name"] = filter.CreateFilter(mbc.ResourceAttributes.DbSystemName.MetricsInclude)
	}
	if mbc.ResourceAttributes.DbSystemName.MetricsExclude != nil {
		mb.resourceAttributeExcludeFilter["db.system.name"] = filter.CreateFilter(mbc.ResourceAttributes.DbSystemName.MetricsExclude)
	}

	for _, op := range options {
		op.apply(mb)
	}
	return mb
}

// NewResourceBuilder returns a new resource builder that should be used to build a resource associated with for the emitted metrics.
func (mb *MetricsBuilder) NewResourceBuilder() *ResourceBuilder {
	return NewResourceBuilder(mb.config.ResourceAttributes)
}

// updateCapacity updates max length of metrics and resource attributes that will be used for the slice capacity.
func (mb *MetricsBuilder) updateCapacity(rm pmetric.ResourceMetrics) {
	if mb.metricsCapacity < rm.ScopeMetrics().At(0).Metrics().Len() {
		mb.metricsCapacity = rm.ScopeMetrics().At(0).Metrics().Len()
	}
}

// ResourceMetricsOption applies changes to provided resource metrics.
type ResourceMetricsOption interface {
	apply(pmetric.ResourceMetrics)
}

type resourceMetricsOptionFunc func(pmetric.ResourceMetrics)

func (rmof resourceMetricsOptionFunc) apply(rm pmetric.ResourceMetrics) {
	rmof(rm)
}

// WithResource sets the provided resource on the emitted ResourceMetrics.
// It's recommended to use ResourceBuilder to create the resource.
func WithResource(res pcommon.Resource) ResourceMetricsOption {
	return resourceMetricsOptionFunc(func(rm pmetric.ResourceMetrics) {
		res.CopyTo(rm.Resource())
	})
}

// WithStartTimeOverride overrides start time for all the resource metrics data points.
// This option should be only used if different start time has to be set on metrics coming from different resources.
func WithStartTimeOverride(start pcommon.Timestamp) ResourceMetricsOption {
	return resourceMetricsOptionFunc(func(rm pmetric.ResourceMetrics) {
		var dps pmetric.NumberDataPointSlice
		metrics := rm.ScopeMetrics().At(0).Metrics()
		for i := 0; i < metrics.Len(); i++ {
			switch metrics.At(i).Type() {
			case pmetric.MetricTypeGauge:
				dps = metrics.At(i).Gauge().DataPoints()
			case pmetric.MetricTypeSum:
				dps = metrics.At(i).Sum().DataPoints()
			}
			for j := 0; j < dps.Len(); j++ {
				dps.At(j).SetStartTimestamp(start)
			}
		}
	})
}

// EmitForResource saves all the generated metrics under a new resource and updates the internal state to be ready for
// recording another set of data points as part of another resource. This function can be helpful when one scraper
// needs to emit metrics from several resources. Otherwise calling this function is not required,
// just `Emit` function can be called instead.
// Resource attributes should be provided as ResourceMetricsOption arguments.
func (mb *MetricsBuilder) EmitForResource(options ...ResourceMetricsOption) {
	rm := pmetric.NewResourceMetrics()
	ils := rm.ScopeMetrics().AppendEmpty()
	ils.Scope().SetName(ScopeName)
	ils.Scope().SetVersion(mb.buildInfo.Version)
	ils.Metrics().EnsureCapacity(mb.metricsCapacity)
	mb.metricCockroachdbClusterLocksCount.emit(ils.Metrics())
	mb.metricCockroachdbClusterQueriesActive.emit(ils.Metrics())
	mb.metricCockroachdbClusterSessionsActive.emit(ils.Metrics())
	mb.metricCockroachdbClusterTransactionsActive.emit(ils.Metrics())
	mb.metricCockroachdbContentionEventsTotal.emit(ils.Metrics())
	mb.metricCockroachdbIndexContentionEvents.emit(ils.Metrics())
	mb.metricCockroachdbIndexReadsTotal.emit(ils.Metrics())
	mb.metricCockroachdbJobsCount.emit(ils.Metrics())
	mb.metricCockroachdbNodesLive.emit(ils.Metrics())
	mb.metricCockroachdbNodesTotal.emit(ils.Metrics())
	mb.metricCockroachdbRangesTotal.emit(ils.Metrics())
	mb.metricCockroachdbRangesUnavailable.emit(ils.Metrics())
	mb.metricCockroachdbRangesUnderReplicated.emit(ils.Metrics())
	mb.metricCockroachdbSchemaChangesActive.emit(ils.Metrics())
	mb.metricCockroachdbSessionMemoryAllocated.emit(ils.Metrics())
	mb.metricCockroachdbStatementBytesReadMean.emit(ils.Metrics())
	mb.metricCockroachdbStatementErrorCount.emit(ils.Metrics())
	mb.metricCockroachdbStatementExecutionCount.emit(ils.Metrics())
	mb.metricCockroachdbStatementLatencyParseMean.emit(ils.Metrics())
	mb.metricCockroachdbStatementLatencyPlanMean.emit(ils.Metrics())
	mb.metricCockroachdbStatementLatencyRunMean.emit(ils.Metrics())
	mb.metricCockroachdbStatementLatencyServiceMean.emit(ils.Metrics())
	mb.metricCockroachdbStatementRetriesMax.emit(ils.Metrics())
	mb.metricCockroachdbStatementRowsReadMean.emit(ils.Metrics())
	mb.metricCockroachdbStatementRowsWrittenMean.emit(ils.Metrics())
	mb.metricCockroachdbTableContentionEvents.emit(ils.Metrics())
	mb.metricCockroachdbTransactionBytesReadMean.emit(ils.Metrics())
	mb.metricCockroachdbTransactionExecutionCount.emit(ils.Metrics())
	mb.metricCockroachdbTransactionLatencyCommitMean.emit(ils.Metrics())
	mb.metricCockroachdbTransactionLatencyRetryMean.emit(ils.Metrics())
	mb.metricCockroachdbTransactionLatencyServiceMean.emit(ils.Metrics())
	mb.metricCockroachdbTransactionRetriesMax.emit(ils.Metrics())
	mb.metricCockroachdbTransactionRowsReadMean.emit(ils.Metrics())
	mb.metricCockroachdbTransactionRowsWrittenMean.emit(ils.Metrics())

	for _, op := range options {
		op.apply(rm)
	}
	for attr, filter := range mb.resourceAttributeIncludeFilter {
		if val, ok := rm.Resource().Attributes().Get(attr); ok && !filter.Matches(val.AsString()) {
			return
		}
	}
	for attr, filter := range mb.resourceAttributeExcludeFilter {
		if val, ok := rm.Resource().Attributes().Get(attr); ok && filter.Matches(val.AsString()) {
			return
		}
	}

	if ils.Metrics().Len() > 0 {
		mb.updateCapacity(rm)
		rm.MoveTo(mb.metricsBuffer.ResourceMetrics().AppendEmpty())
	}
}

// Emit returns all the metrics accumulated by the metrics builder and updates the internal state to be ready for
// recording another set of metrics. This function will be responsible for applying all the transformations required to
// produce metric representation defined in metadata and user config, e.g. delta or cumulative.
func (mb *MetricsBuilder) Emit(options ...ResourceMetricsOption) pmetric.Metrics {
	mb.EmitForResource(options...)
	metrics := mb.metricsBuffer
	mb.metricsBuffer = pmetric.NewMetrics()
	return metrics
}

